package ec.edu.monster.vista;

import ec.edu.monster.modelo.*;
import java.awt.*;
import java.util.List;
import javax.swing.*;

/** Conversor y su historial en dos tarjetas, siguiendo la pantalla SOAP. */
public final class ConversionView extends JFrame {
    private final JComboBox<Categoria> categoria=new JComboBox<>();private final JComboBox<Unidad> origen=new JComboBox<>(),destino=new JComboBox<>();
    private final JTextField valor=new JTextField("0");private final JButton convertir=new JButton("Convertir"),limpiar=new JButton("Limpiar"),volver=new JButton("Volver al inicio");
    private final JLabel estado=new JLabel("Listo para convertir",SwingConstants.CENTER);private final DefaultListModel<String> history=new DefaultListModel<>();
    private final JList<String> list=new JList<>(history);
    public ConversionView(){super("Conversión de Unidades Monster | Conversor");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1180,760);setMinimumSize(new Dimension(940,620));setLocationRelativeTo(null);setExtendedState(JFrame.MAXIMIZED_BOTH);
        JPanel root=new JPanel(new BorderLayout());root.setBackground(new Color(0xF5F8FC));root.add(nav(),BorderLayout.NORTH);JPanel area=new JPanel(new GridBagLayout());area.setBackground(new Color(0xF5F8FC));area.setBorder(BorderFactory.createEmptyBorder(38,42,34,42));
        JPanel cards=new JPanel(new GridLayout(1,2,28,0));cards.setOpaque(false);cards.add(form());cards.add(historyCard());GridBagConstraints g=new GridBagConstraints();g.weightx=1;g.weighty=1;g.fill=GridBagConstraints.BOTH;area.add(cards,g);root.add(area,BorderLayout.CENTER);setContentPane(root);}
    private JPanel nav(){JPanel p=new JPanel(new BorderLayout());p.setBackground(Estilo.OSCURO);p.setBorder(BorderFactory.createEmptyBorder(13,28,13,28));JPanel ts=new JPanel();ts.setOpaque(false);ts.setLayout(new BoxLayout(ts,BoxLayout.Y_AXIS));JLabel b=new JLabel("MONSTER");b.setForeground(Color.WHITE);b.setFont(Estilo.font(16,true));JLabel sub=new JLabel("Conversor de unidades · longitud, masa y temperatura");sub.setForeground(new Color(0xB8D2FF));sub.setFont(Estilo.font(12,false));ts.add(b);ts.add(sub);p.add(ts,BorderLayout.WEST);Estilo.button(volver,false);p.add(volver,BorderLayout.EAST);return p;}
    private JPanel form(){JPanel p=card();p.setLayout(new BorderLayout(0,20));p.add(title("Conversor de unidades","Realiza una conversión con las opciones del servidor."),BorderLayout.NORTH);
        JPanel fields=new JPanel(new GridLayout(4,1,0,14));fields.setOpaque(false);fields.add(field("Tipo de conversión",categoria));fields.add(field("Valor",valor));JPanel pair=new JPanel(new GridLayout(1,2,14,0));pair.setOpaque(false);pair.add(field("Unidad inicial",origen));pair.add(field("Unidad final",destino));fields.add(pair);
        JPanel actions=new JPanel(new GridLayout(1,2,12,0));actions.setOpaque(false);Estilo.button(convertir,true);Estilo.button(limpiar,false);actions.add(convertir);actions.add(limpiar);fields.add(actions);p.add(fields,BorderLayout.CENTER);
        estado.setOpaque(true);estado.setFont(Estilo.font(13,true));estado.setForeground(new Color(0x0F7A52));estado.setBackground(new Color(0xE7F6EF));estado.setBorder(BorderFactory.createEmptyBorder(12,14,12,14));p.add(estado,BorderLayout.SOUTH);return p;}
    private JPanel historyCard(){JPanel p=card();p.setLayout(new BorderLayout(0,16));p.add(title("Historial de conversiones","Resultados obtenidos en esta sesión."),BorderLayout.NORTH);list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);list.setFont(Estilo.font(14,false));list.setForeground(Estilo.TEXTO);list.setFixedCellHeight(64);list.setCellRenderer(new DefaultListCellRenderer(){@Override public Component getListCellRendererComponent(JList<?> l,Object v,int i,boolean s,boolean f){super.getListCellRendererComponent(l,v,i,s,f);setText("<html><div style='padding:5px 2px'>"+v+"</div></html>");setBorder(BorderFactory.createMatteBorder(0,0,1,0,Estilo.DIVISOR));setBackground(s?Estilo.SUAVE:Color.WHITE);setForeground(Estilo.TEXTO);return this;}});JScrollPane scroll=new JScrollPane(list);scroll.setBorder(BorderFactory.createLineBorder(Estilo.BORDE));scroll.getViewport().setBackground(Color.WHITE);p.add(scroll,BorderLayout.CENTER);JLabel note=new JLabel("El historial se conserva mientras esta ventana esté abierta.");note.setForeground(Estilo.SECUNDARIO);note.setFont(Estilo.font(12,false));p.add(note,BorderLayout.SOUTH);return p;}
    private JPanel card(){JPanel p=new JPanel();p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(Estilo.DIVISOR),BorderFactory.createEmptyBorder(24,24,24,24)));return p;}
    private JPanel title(String h,String sub){JPanel p=new JPanel();p.setOpaque(false);p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel a=new JLabel(h);a.setForeground(Estilo.OSCURO);a.setFont(Estilo.font(22,true));JLabel b=new JLabel(sub);b.setForeground(Estilo.SECUNDARIO);b.setFont(Estilo.font(13,false));b.setBorder(BorderFactory.createEmptyBorder(4,0,0,0));p.add(a);p.add(b);return p;}
    private JPanel field(String name,java.awt.Component control){JPanel p=new JPanel(new BorderLayout(0,7));p.setOpaque(false);JLabel l=new JLabel(name);l.setForeground(Estilo.TEXTO);l.setFont(Estilo.font(14,true));control.setFont(Estilo.font(14,false));control.setPreferredSize(new Dimension(180,48));if(control instanceof JComboBox<?> c){c.setBackground(Color.WHITE);c.setForeground(Estilo.TEXTO);}else if(control instanceof JTextField t){Estilo.field(t);t.setToolTipText("Escribe el valor numérico que deseas convertir");}p.add(l,BorderLayout.NORTH);p.add(control,BorderLayout.CENTER);return p;}
    public JComboBox<Categoria> categoria(){return categoria;}public JComboBox<Unidad> origen(){return origen;}public JComboBox<Unidad> destino(){return destino;}public JTextField valor(){return valor;}public JButton convertir(){return convertir;}public JButton limpiar(){return limpiar;}public JButton salir(){return volver;}
    public void categorias(List<Categoria> list){categoria.removeAllItems();list.stream().filter(Categoria::convertible).forEach(categoria::addItem);}
    public void unidades(List<Unidad> list){origen.removeAllItems();destino.removeAllItems();list.forEach(origen::addItem);list.forEach(destino::addItem);if(destino.getItemCount()>1)destino.setSelectedIndex(1);}
    public void estado(String message,boolean error){estado.setText(message);estado.setBackground(error?new Color(0xFCEBE8):new Color(0xE7F6EF));estado.setForeground(error?Estilo.ERROR:new Color(0x0F7A52));}
    public void historial(String entry){history.insertElementAt(entry,0);}public void procesando(boolean v){convertir.setEnabled(!v);categoria.setEnabled(!v);origen.setEnabled(!v);destino.setEnabled(!v);valor.setEnabled(!v);if(v)estado("Consultando el servidor…",false);}
}
